catalog_script_client.script:
function onSubmit() {

    // Clear any existing messages from previous validation attempts
    g_form.clearMessages();

    //debugger;

    if (g_scratchpad.isFormValid) {
        return true;
    }

    var actionName = g_form.getActionName();

    // Check for valid Start Date and then End Date.  If either not valid, do  not submit.
    var startDate = g_form.getValue('telework_start_date');
    var endDate = g_form.getValue("telework_end_date");
    var format = g_user_date_format; // Get date format used
    var msg = "";

    // Begin with Start Date verification
    var gaStartDate = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMTelWrkUtils');
    gaStartDate.addParam('sysparm_name', 'checkDateYear');
    gaStartDate.addParam('sysparm_date_to_check', startDate);
    gaStartDate.addParam('sysparm_other_date', endDate);
    gaStartDate.addParam('sysparm_is_start', "true");
    gaStartDate.getXMLAnswer(resultStartDateCheck);

    // GlideAjax callback function - Verify Start Date
    function resultStartDateCheck(answerStartDate) {
        var resultsStartDateObj = JSON.parse(answerStartDate);

        if (resultsStartDateObj.goodYear == "false") {
            g_scratchpad.isFormValid = false;
            msg = getMessage('x_hccc_hoc_ohs.telework_start_date_year_bad');
            g_form.addErrorMessage(msg);
            return;
        }
        // If End Date is empty, skip comparing dates
        if (endDate != "") {

            // If Start date is after End date, show error message
            // 1 (true) if start is greater than end, 0 if end is greater than start of if the same, -1 if either is in invalid format
            var isStartAfterEnd = compareDates(startDate, format, endDate, format);
            if (isStartAfterEnd) {
                g_scratchpad.isFormValid = false;
                msg = getMessage('x_hccc_hoc_ohs.start_date_before_end_date');
                g_form.addErrorMessage(msg);
                return;
            }
        }

        // Do End Date verification
        var gaEndDate = new GlideAjax('x_hccc_hoc_ohs.HoCOHSMTelWrkUtils');
        gaEndDate.addParam('sysparm_name', 'checkDateYear');
        gaEndDate.addParam('sysparm_date_to_check', endDate);
        gaEndDate.addParam('sysparm_other_date', startDate);
        gaEndDate.addParam('sysparm_is_start', "false");
        gaEndDate.getXMLAnswer(resultEndDateCheck);

    }

    // GlideAjax callback function - Verify End Date
    function resultEndDateCheck(answerEndDate) {
        var resultsEndDateObj = JSON.parse(answerEndDate);

        if (resultsEndDateObj.goodYear === "false") {
            g_scratchpad.isFormValid = false;
            msg = getMessage('x_hccc_hoc_ohs.telework_end_date_year_bad');
            g_form.addErrorMessage(msg);
            return;
        }

        // If Start Date is empty, skip comparing dates
        if (startDate != "") {

            // If Start date is after End date, show error message
            // 1 (true) if start is greater than end, 0 if end is greater than start of if the same, -1 if either is in invalid format
            var isEndBeforeStart = compareDates(startDate, format, endDate, format);
            if (isEndBeforeStart) {
                g_scratchpad.isFormValid = false;
                msg = getMessage('x_hccc_hoc_ohs.end_date_after_start_date');
                g_form.addErrorMessage(msg);
                return;
            }
        }
        g_scratchpad.isFormValid = true;
        g_form.submit(actionName);
    }

    return false;
}
